validator:
function validate(input) {
  const [{ Employees = [] }] = input;
  const ids = new Set();
  for (const [id, name] of Employees) {
    if (id === null || id < 1) return 'Every employee needs a positive employee_id.';
    if (ids.has(id)) return `employee_id ${id} appears twice in Employees.`;
    ids.add(id);
    if (name === null) return `Employee ${id} needs a name.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  // M-names, names with an m elsewhere, and names with no m at all.
  const names = ['Meir', 'Michael', 'Mary', 'Mo', 'Emma', 'Kim', 'Ahmed', 'Sam', 'Juan', 'Kannon', 'Addilyn', 'Bob'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const count = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const ids = [];
  for (let id = 1; ids.length < count; id++) if (size !== 'small' || rand() < 0.7) ids.push(id);
  // Shuffle so the stored order differs from the employee_id order the output needs.
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Employees = ids.map(id => [id, pick(names), 1000 + 100 * Math.floor(rand() * 90)]);
  return [{ Employees }];
}
